      "entry": "./example.html"
    },
    "useCase": {
      "query": {
        "en": "Use the html-ppt-testing-safety-alert template to create an incident review / safety review deck. Use red-black hazard stripes, red strikethroughs, L1/L2/L3 tier cards, and policy-yaml code blocks. First ask me for the incident timeline, root cause, and impact scope.",
        "zh-CN": "用 html-ppt-testing-safety-alert 模板做一份事故复盘 / 安全评审 PPT。红黑 hazard 条 + 红色删除线 + L1/L2/L3 tier 卡片 + policy-yaml 代码块。先告诉我事件时间线、根因、影响范围。"
      },
      "exampleOutputs": [
        {
          "path": "./example.html",
          "title": "Html Ppt Testing Safety Alert"
        }
      ]
    },
    "context": {
      "skills": [
        {
          "path": "./SKILL.md"
        }
      ],
